// Unit test for orchestrator
describe("ExportOrchestrator", () => {
  it("should skip already processed exports", async () => {
    const mockRequest = { id: "123", status: "completed" };
    const orch = new ExportOrchestrator();
    const result = await orch.run({ bindingData: mockRequest });
    expect(result.skipped).toBe(true);
